inline void program_logic_update(unsigned long nowMs)
{
  static unsigned long s_lastMs = 0;
  float dt = 0.016f;
  if(s_lastMs != 0 && nowMs > s_lastMs)
  {
    dt = (float)(nowMs - s_lastMs) * 0.001f;
    if(dt > 0.050f) dt = 0.050f;
  }
  s_lastMs = nowMs;

  for(int i = 0; i < 7; i++)
  {
    ProgramObject &obj = objects[i];
    // User script section per object
    switch(i)
    {
      case 0:
        break;
      case 1:
        break;
      case 2:
        break;
      case 3:
        if(obj.vx == 0.0f && obj.vy == 0.0f)
        {
          obj.vx = 70.0f;  // px/s
          obj.vy = 50.0f;  // px/s
        }

        {
          int frameId = 0;
          if(obj.inst.clip && obj.inst.clip->frameCount > 0)
            frameId = obj.inst.clip->frames[obj.inst.frameIndex % obj.inst.clip->frameCount];
          int halfW = 8;
          int halfH = 8;
          if(obj.inst.clip && obj.inst.clip->atlasRef && obj.inst.clip->atlasRef->atlas)
          {
            Sprites *a = obj.inst.clip->atlasRef->atlas;
            halfW = a->xres(frameId) / 2;
            halfH = a->yres(frameId) / 2;
          }

          int minX = halfW;
          int maxX = 320 - halfW;
          int minY = halfH;
          int maxY = 200 - halfH;
          if(maxX < minX) { minX = maxX = 160; }
          if(maxY < minY) { minY = maxY = 100; }

          obj.inst.x += (int)roundf(obj.vx * dt);
          obj.inst.y += (int)roundf(obj.vy * dt);

          if(obj.inst.x < minX) { obj.inst.x = minX; obj.vx = fabsf(obj.vx); }
          if(obj.inst.x > maxX) { obj.inst.x = maxX; obj.vx = -fabsf(obj.vx); }
          if(obj.inst.y < minY) { obj.inst.y = minY; obj.vy = fabsf(obj.vy); }
          if(obj.inst.y > maxY) { obj.inst.y = maxY; obj.vy = -fabsf(obj.vy); }
        }

        obj.drawMode = 1;      // rotated
        obj.angle += 90.0f * dt; // deg/s
        if(obj.angle >= 360.0f) obj.angle -= 360.0f;
        
        set_state(obj, 1);     // walk
        break;
      case 4:
        obj.drawMode = 2;
        obj.scale = 1.0f + 0.6f * sinf((float)nowMs * 0.003f);
        break;
      case 5:
        break;
      case 6:
        break;
      default: break;
    }

    obj.inst.x = (int)obj.inst.x;
    obj.inst.y = (int)obj.inst.y;
    anim_update(obj.inst, nowMs);
  }
}

inline void program_logic_draw(Graphics &graphics)
{
  for(int i = 0; i < 7; i++)
  {
    ProgramObject &obj = objects[i];
    if(!obj.inst.visible) continue;
    if(obj.drawMode == 1) sprite_draw_rotated(graphics, obj.inst, obj.angle);
    else if(obj.drawMode == 2) sprite_draw_scaled(graphics, obj.inst, obj.scale);
    else anim_draw(graphics, obj.inst);
  }
}

